contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(bool doInit, address newLog) internal {
        vm.assume(newLog != address(0));
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(newLog) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(bool doInit, address newLog) public {
